#include <stdio.h>
#include <math.h>

int main(void) {
    double x0, y0, x1, y1, x2, y2, x3, y3;
    if (scanf("%lf %lf %lf %lf %lf %lf %lf %lf",
              &x0, &y0, &x1, &y1, &x2, &y2, &x3, &y3) != 8) {
        return 0;
    }

    double ax = x1 - x0, ay = y1 - y0;
    double bx = x3 - x2, by = y3 - y2;

    const double EPS = 1e-10;

    double cross = ax * by - ay * bx;
    double dot   = ax * bx + ay * by;

    if (fabs(cross) < EPS) {
        printf("2\n");   // parallel
    } else if (fabs(dot) < EPS) {
        printf("1\n");   // orthogonal
    } else {
        printf("0\n");   // neither
    }

    return 0;
}

