import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        double nextDouble() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            double val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + (c - '0');
                c = read();
            }

            if (c == '.') {
                double mul = 0.1;
                c = read();
                while (c >= '0' && c <= '9') {
                    val += (c - '0') * mul;
                    mul *= 0.1;
                    c = read();
                }
            }

            return val * sign;
        }

        boolean hasNext() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return false;
            } while (c <= ' ');
            ptr--;
            return true;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        int q = (int) fs.nextDouble();
        final double EPS = 1e-10;

        for (int i = 0; i < q; i++) {
            double x0 = fs.nextDouble(), y0 = fs.nextDouble();
            double x1 = fs.nextDouble(), y1 = fs.nextDouble();
            double x2 = fs.nextDouble(), y2 = fs.nextDouble();
            double x3 = fs.nextDouble(), y3 = fs.nextDouble();

            double ax = x1 - x0, ay = y1 - y0;
            double bx = x3 - x2, by = y3 - y2;

            double cross = ax * by - ay * bx;
            double dot = ax * bx + ay * by;

            if (Math.abs(cross) < EPS) {
                out.append(2);
            } else if (Math.abs(dot) < EPS) {
                out.append(1);
            } else {
                out.append(0);
            }
            out.append('\n');
        }

        System.out.print(out.toString());
    }
}

